import os, sys, re
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from mlib import *
def common_tail(slug, extra_comp=""):
    r = rd(f"toys10/{slug}/README.md"); comp = section(r, "Compliance"); risks = section(r, "Risks"); ver = section(r, "What I verified"); prod = section(r, "Designed production BOM")
    return r, comp, risks, ver, prod
ELEC = {
 "01-reflex-raja": ("Reflex Raja", "arcade", "Hold nothing (or button 1) while switching on = Reflex Raja", ["Press a button to start: after a hidden 2-6 s all four lamps light and the buzzer sounds; first press wins a point.", "Press early: that player is locked out for the round and loses a point; two simultaneous presses replay.", "First to 5 points wins; the winner's lamp stays lit; 20 rounds: delays always between 2 and 6 s."]),
 "02-taal-memory": ("Taal Memory", "arcade", "Hold button 2 while switching on = Taal Memory", ["Play the sequence back on the pads; a wrong pad ends the game and the best length flashes.", "Check all four pads sound different notes (262, 330, 392, 523 Hz) and light their lamp.", "Power-cycle: the sequence changes (noise seed) but replays exactly within a game."]),
 "03-aloo-bomb": ("Aloo Bomb", "arcade", "Hold button 3 while switching on = Aloo Bomb", ["Press start: beeps every 1 s, faster (0.6/0.3/0.12 s) in the last 5 s; the explosion sound ends the round (fuse 20-60 s hidden).", "Run 5 rounds: fuse lengths vary; the explosion always follows the fast beeps.", "Battery door must be screw-closed on the production housing."]),
}
def gen_elec(slug, c):
    name, board, sel, tests = c; r, comp, risks, ver, prod = common_tail(slug)
    how = section(r, "How it plays")
    bi = board_info("utility10/pcb/release/arcade", "desi_arcade")
    L = [f"# {name}: manufacturing manual", "", "> **Status: design only.** The three arcade games share one board (**Desi Arcade rev B**) and one firmware image; nothing has been built or tested with children.", "", "## 1. What is built", "", how, "", "One board runs three games: hold a button while switching on to choose (none/button 1 = Reflex Raja, button 2 = Taal Memory, button 3 = Aloo Bomb). The blink count at power-on equals the game number.", "", "## 2. Deliverables", "", "| Item | Where |", "|---|---|",
         f"| PCB: Gerbers, BOM, CPL, KiCad project | `utility10/pcb/release/arcade/` ({'order-ready: all automatic checks pass' if bi['rdy']['order_ready'] else 'NOT order-ready'}) |", "| Firmware for the board (8 MHz, rev B pin map) | `toys10/electronic/release/pcb/desi_arcade_rev_b.hex` (build: `make pcb` in `toys10/electronic`) |", "| Engine + tests | `toys10/electronic/lib/toycore.c`, 80,045 host checks pass |", "| Nano bench demo | `toys10/electronic/release/<game>.hex` |", "", "## 3. Bill of materials", "", "### 3a. Board parts", "", bom_table(bi["bom"]), "", "### 3b. Bought-in and mechanical (estimates, ~2,000 units)", "", prod, "",
         "- 4 arcade push buttons, 30 mm, with 5 V LED lamp (3-wire leads to the JST-PH 3-pin sockets J5-J8: button, lamp, GND), housing (ABS, or 3D-printed/laser-cut MDF for the first 500), 3 x AAA holder, button caps/labels.", "", "## 4. Make the board", "", "Order bare PCBs and SMT assembly per `manuals/STANDARD_PROCEDURES.md` A and B using the files in `utility10/pcb/release/arcade/`; solder the hand/THT parts (JST sockets J5-J8, battery JST J1, slide switch, buzzer BZ1, ISP header).", "", "## 5. Program", "", "```", "avrdude -p m328p -c usbasp -U lfuse:w:0xE2:m -U hfuse:w:0xD9:m -U efuse:w:0xFD:m", "avrdude -p m328p -c usbasp -U flash:w:toys10/electronic/release/pcb/desi_arcade_rev_b.hex:i", "```", "(8 MHz internal, brown-out 2.7 V: 3 x AAA runs from 4.5 V down to about 2.7 V.)", "", "Pin map of the rev B board (generated from the PCB spec): buttons D0, D1, D2, A5; lamp LEDs A1-A4 (330 ohm); buzzer D9; random-seed noise on A0.", "",
         "## 6. Bring-up", "", "1. Batteries in, switch on: +4V5 at TP1 = 4.2-4.6 V; current under 20 mA idle.", "2. Power-on blink count = selected game; hold each button in turn to select each game.", "3. Each button lights its own lamp; the buzzer sounds.", "", "## 7. Assemble the toy", "", "Mount four arcade buttons in the lid, wire to J5-J8, fit the board on standoffs, screw-closed battery door, label the game-select instruction on the base.", "", f"## 8. Functional test: {name} (every unit)", ""] + [f"{i+1}. {t}" for i, t in enumerate(tests)] + ["", f"Game select for this game: {sel}.", "", "Record on `manuals/templates/eol_test_sheet.md`.", "", "## 9. Packaging, compliance", "", comp, "", "Add: age grade label, small-parts warning, battery warning, Legal Metrology marks; buzzer level not above 85 dB at 25 cm (verify).", "", "## 10. Known limits", "", ver, "", risks, ""]
    open(os.path.join(ROOT, "toys10", slug, "MANUFACTURING_MANUAL.md"), "w").write("\n".join(L))
def gen_br():
    slug = "04-beat-runner"; r, comp, risks, ver, prod = common_tail(slug); how = section(r, "How it plays")
    rel = "utility10/pcb/release/beatrunner"; ok = os.path.exists(os.path.join(ROOT, rel, "README.md"))
    L = ["# Beat Runner: manufacturing manual", "", "> **Status: design only; nothing built.**", "", "## 1. What is built", "", how, "", "## 2. Deliverables", "", "| Item | Where |", "|---|---|", f"| PCB (150 x 46 mm, 2 x 74HC595, 16 LEDs) | `{rel}/` " + ("(released)" if ok else "(**not yet released**: routing/verification unfinished)") + " |", "| Firmware for the board | `toys10/electronic/release/pcb/beat_runner_rev_b.hex` (buzzer on D9, build `make pcb`) |", "| Engine + tests | `toycore.c` (`br_*`) |", ""]
    if ok:
        bi = board_info(rel, "beat_runner"); L += ["## 3. Bill of materials", "", "### 3a. Board parts", "", bom_table(bi["bom"]), ""]
    L += ["### 3b. Bought-in items", "", prod, "", "- One 30 mm arcade button (J3), 3 x AAA holder + switch, enclosure, 16 x red 0603 LEDs are on the board.", "", "## 4. Make, program, test", "", "1. Order PCB and SMT assembly per STANDARD_PROCEDURES A/B; solder THT parts (battery JST, switch, buzzer, button socket, ISP).", "2. Fuses and flash: `avrdude -p m328p -c usbasp -U lfuse:w:0xE2:m -U hfuse:w:0xD9:m -U efuse:w:0xFD:m` then `-U flash:w:toys10/electronic/release/pcb/beat_runner_rev_b.hex:i`.", "3. Pin map: data D11, shift clock D12, latch D13 (shared with the ISP header: the LEDs flicker while programming), button D2, buzzer D9.", "4. Test: LEDs light in sequence as notes scroll; press when a note reaches LED 0: perfect = 3 points (high beep), good at LED 1; 5 misses end the game (all LEDs light); speed rises every 40 steps (400 ms to 150 ms).", "5. Current: at most a few LEDs lit at once (74HC595 allows 70 mA total); idle current under 15 mA.", "", "## 5. Packaging, compliance", "", comp, "", "## 6. Known limits", "", ver, "", risks, ""]
    open(os.path.join(ROOT, "toys10", slug, "MANUFACTURING_MANUAL.md"), "w").write("\n".join(L))
