def gen_laser(slug, c):
    r, comp, risks, ver, prod = common_tail(slug); how = section(r, "How it plays")
    L = [f"# {c['name']}: manufacturing manual", "", "> **Status: design only; nothing has been cut or assembled.**", "", "## 1. What is made", "", how, "", "## 2. Files and materials", ""] + [f"- {x}" for x in c["files"]] + ["", f"- Material: **{c['mat']}**; layout/sheet: {c['sheet']}.", "", "Cost per set (about 2,000 units, estimate):", "", prod, "", "## 3. Making it", "", "Follow `manuals/STANDARD_PROCEDURES.md` section H (laser cutting) for kerf tests and finishing, then:", ""] + [f"{i+1}. {s}" for i, s in enumerate(c["steps"])] + ["", "## 4. Inspection (sample per batch)", ""] + [f"- {t}" for t in c["tests"]] + ["", "Record on `manuals/templates/eol_test_sheet.md`.", "", "## 5. Packaging and compliance", "", comp, "", "Add the age grade, small-parts warning, Legal Metrology marks and a printed instruction leaflet.", "", "## 6. Risks and limits", ""] + [f"- {x}" for x in c["risks"]] + ["", risks, "", ver, ""]
    open(os.path.join(ROOT, "toys10", slug, "MANUFACTURING_MANUAL.md"), "w").write("\n".join(L))
def gen_rocket():
    slug = "06-paper-rocket"; r, comp, risks, ver, prod = common_tail(slug)
    L = ["# Paper Rocket Air Launcher: manufacturing manual", "", "> **Status: design only; nothing built or pressure-tested. This is a pressurised projectile toy: do not sell before a design review against the toy standard and a lab test. The 0.3 bar limit below is a design limit, not a safety certification.**", "", "## 1. What is made", "", "A PVC pressure chamber and 19 mm barrel with a bicycle-pump connector, a spring relief valve set at about **0.29 bar gauge** (launch energy 0.5 J, range about 16 m at 42 degrees: estimates), a trigger valve and rolled-paper rockets with foam noses (templates to be printed).", "", "No drawings exist yet; this is a plumbing assembly. Calculation: `toys10/docs/results_rocket.md` (a first draft with a 1 bar valve gave 2.8 J, five times the design limit, so the low-pressure valve is mandatory).", "", "## 2. Parts (about Rs 310 at volume, estimate)", "", prod, "", "## 3. Assembly and pressure test (workshop)", "", "1. Cut PVC chamber and barrel; deburr; solvent-weld fittings with the pipe-cement manufacturer's cure time (24 h).", "2. Fit the spring relief valve (0.29 bar) in the chamber wall, trigger valve, bicycle-pump connector with a check valve.", "3. **Proof test every unit** to 1.5 x relief pressure (about 0.45 bar) with water-immersion or soapy-water leak check behind a shield; no leaks, no deformation.", "4. **Relief valve check:** pump until the valve opens: pressure must never exceed 0.35 bar on a calibrated gauge (reject otherwise).", "5. Fire a test rocket at a safe angle with the barrel pointed away from people; measure range and compare with the estimate.", "6. Pack with 6 paper rockets, foam noses, a printed instruction sheet and the warnings below.", "", "## 4. Required warnings", "", "NEVER aim at people or animals; eye protection recommended; adult supervision; 8+; no modification of the relief valve.", "", "## 5. Compliance", "", comp, "", "Projectile safety is the whole risk: get a lab review (toy standard, pressure-vessel margin) before selling.", "", "## 6. Known limits", "", ver, "", risks, ""]
    open(os.path.join(ROOT, "toys10", slug, "MANUFACTURING_MANUAL.md"), "w").write("\n".join(L))
